using UnityEngine;using System;using System.Text;
public static class ValidateRoadCamera{public static string Main(){if(!Application.isPlaying)throw new Exception("Play Mode required");var report=new StringBuilder();foreach(var source in UnityEngine.Object.FindObjectsByType<PickupController>(FindObjectsSortMode.None)){GameObject copy=null;int checks=0;void Check(bool v,string m){if(!v)throw new Exception(source.name+": "+m);checks++;}try{copy=UnityEngine.Object.Instantiate(source.gameObject,new Vector3(10000,0,10000),Quaternion.identity);var p=copy.GetComponent<PickupController>();var b=p.GetComponent<BicycleController>();b.SetRidden(true);copy.GetComponent<CharacterController>().enabled=false;float intensity=p.roadCameraIntensity;
 float Run(bool rough,float speed){copy.transform.position=new Vector3(10000,0,10000);p.ResetRoadCamera();float energy=0;for(int i=0;i<200;i++){copy.transform.position+=new Vector3(0,0,speed*.02f);var pos=copy.transform.position;pos.y=rough?.025f*Mathf.Sin(i*.5f):0;copy.transform.position=pos;p.UpdateRoadCamera(.02f);Check(Mathf.Abs(p.RoadCameraOffset.y)<=.0061f&&Mathf.Abs(p.RoadCameraOffset.x)<=.0021f&&p.RoadCameraAngles.magnitude<.135f,"Comfort bounds");energy+=p.RoadCameraOffset.sqrMagnitude;}return energy;}
 float flat=Run(false,8),rough=Run(true,8);Check(flat>0,"Small smooth-road vibration");Check(rough>flat*2,"Uneven ground adds capped vibration");float reverse=Run(false,-8);Check(reverse>0,"Reverse vibration");var saved=p.RoadCameraOffset;p.UpdateRoadCamera(0);Check(saved==p.RoadCameraOffset,"Paused vibration does not advance");for(int i=0;i<150;i++)p.UpdateRoadCamera(.02f);Check(p.RoadCameraOffset.magnitude<.000001f&&p.RoadCameraAngles.magnitude<.00001f,"Parked camera settles");p.roadCameraIntensity=0;Run(true,8);Check(p.RoadCameraOffset==Vector3.zero&&p.RoadCameraAngles==Vector3.zero,"Intensity zero disables");p.roadCameraIntensity=intensity;Run(true,8);p.ResetRoadCamera();Check(p.RoadCameraOffset==Vector3.zero&&p.RoadCameraAngles==Vector3.zero,"Mount/exit reset clears offsets");report.AppendLine(source.name+": PASS; rough/flat energy="+(rough/flat).ToString("F2"));
 }finally{if(copy)UnityEngine.Object.DestroyImmediate(copy);}}System.IO.File.WriteAllText("output/Pickups/road-camera-validation.txt",report.ToString());return report.ToString();}}
